      // postbuild rewrites this assignment to the per-build nonce'd worker
      // filename (lead "/" for the normal build, relative for the SVG build).
      window.__SW_FILE__ = "./4mkcjl.js?v=hoho-20261012-10";
      window.__HOHOGAMES_API_ORIGIN__ = location.origin;
      window.__swRegistration = navigator.serviceWorker && !/(\.|^)jsdelivr\.net$/i.test(location.hostname)
        ? (function () {
            var FILE = new URL(window.__SW_FILE__, location.href).pathname.split("/").pop();
            var userInteracted = false;
            var noteInteraction = function () {
              userInteracted = true;
            };
            window.addEventListener("pointerdown", noteInteraction, { capture: true, once: true });
            window.addEventListener("keydown", noteInteraction, { capture: true, once: true });
            window.addEventListener("click", noteInteraction, { capture: true, once: true });
            var base = function (u) {
              try {
                return new URL(u, location.href).pathname.split("/").pop();
              } catch (e) {
                return String(u);
              }
            };
            // Every deploy renames the worker script, so a registration left
            // over from a previous build can never update itself (its script
            // URL now 404s) and would keep controlling the page forever — on a
            // CDN nothing tells it to die. Drop any registration whose worker
            // isn't THIS build's file before registering ours. Not the one at
            // our own scope: the register() below already swaps its worker,
            // and unregistering it as well deletes that new worker as soon as
            // the tab closes, so the next visit starts over without one.
            var scope = new URL(".", new URL(window.__SW_FILE__, location.href)).href;
            navigator.serviceWorker
              .getRegistrations()
              .then(function (regs) {
                regs.forEach(function (r) {
                  var w = r.active || r.waiting || r.installing;
                  if (r.scope !== scope && w && base(w.scriptURL) !== FILE) r.unregister();
                });
              })
              .catch(function () {});
            return navigator.serviceWorker
              // updateViaCache "all": the worker's filename is a per-build
              // nonce, so its bytes can never change under one URL. Without
              // this the browser re-fetches it on every navigation, which on
              // a bucket is a billed GET per page view for nothing.
              .register(window.__SW_FILE__, { updateViaCache: "all" })
              .then(function (reg) {
                // If this document loaded WITHOUT the current worker in
                // control, the proxy sits on a 45s control-timeout before
                // falling back. That happens on a hard reload, a first visit,
                // or when a stale worker from a previous deploy still controls
                // the page while ours installs. Grab control fast: give claim
                // a short grace window, and if we're still uncontrolled — or
                // controlled by the WRONG (stale) worker — reload ONCE
                // (sessionStorage-guarded so we can never loop).
                function currentControls() {
                  var c = navigator.serviceWorker.controller;
                  return !!c && base(c.scriptURL) === FILE;
                }
                if (currentControls()) {
                  sessionStorage.removeItem("__sw_reload");
                  return reg;
                }
                if (sessionStorage.getItem("__sw_reload")) return reg;
                navigator.serviceWorker.ready.then(function () {
                  if (currentControls()) return;
                  var settled = false;
                  var onCtrl = function () {
                    if (!currentControls()) return;
                    settled = true;
                    navigator.serviceWorker.removeEventListener(
                      "controllerchange",
                      onCtrl
                    );
                  };
                  navigator.serviceWorker.addEventListener(
                    "controllerchange",
                    onCtrl
                  );
                  setTimeout(function () {
                    navigator.serviceWorker.removeEventListener(
                      "controllerchange",
                      onCtrl
                    );
                    if (!settled && !currentControls()) {
                      sessionStorage.setItem("__sw_reload", "1");
                      if (!userInteracted) location.reload();
                    }
                  }, 1200);
                });
                return reg;
              })
              .catch(function (err) {
                console.error("[sw] registration failed:", err);
                return null;
              });
          })()
        : Promise.resolve(null);

