/**/
(function () {
  if (location.pathname === "/embed") return;
  var mount = document.getElementById("_xi9j4u0");
  var scaleKey = "hoho-interface-scale";
  var applyScale = function (value) {
    var scale = Math.max(70, Math.min(140, Number(value) || 100));
    document.documentElement.style.zoom = String(scale / 100);
    try { localStorage.setItem(scaleKey, String(scale)); } catch (e) {}
    return scale;
  };
  var install = function () {
    var shadow = mount && mount.shadowRoot;
    if (!shadow) {
      requestAnimationFrame(install);
      return;
    }
    var clean = function () {
      shadow.querySelectorAll('a[href*="discord.gg"]').forEach(function (link) { link.remove(); });
      var dock = shadow.querySelector("div._68jxnii.shrink-0.flex.flex-col.w-10");
      if (dock) {
        dock.querySelectorAll("button[aria-label],a[aria-label],[role=button][aria-label]").forEach(function (control) {
          var label = (control.getAttribute("aria-label") || "").replace(/\s+/g, " ").trim();
          if (["AI", "AI Assistant", "Chat", "Chatrooms", "Members", "Changelog"].includes(label)) {
            var item = control.closest(".group.relative.w-full") || control;
            item.remove();
          }
        });
      }
      if (dock && dock.dataset.hohoDock !== "true") {
        dock.dataset.hohoDock = "true";
        dock.classList.add("hoho-bottom-dock");
        dock.style.cssText = "position:fixed;top:auto;right:auto;bottom:max(12px,env(safe-area-inset-bottom));left:50%;z-index:2147483646;display:flex;flex-direction:row;align-items:center;gap:8px;width:max-content;max-width:calc(100vw - 16px);height:auto;overflow-x:auto;overflow-y:hidden;padding:7px;border:1px solid rgba(255,255,255,.18);border-radius:15px;background:rgba(10,10,10,.9);box-shadow:0 8px 28px rgba(0,0,0,.48);transform:translateX(-50%);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);pointer-events:auto;scrollbar-width:none";
        Array.prototype.forEach.call(dock.children, function (group, index) {
          if (index === 1) {
            group.style.cssText = "width:1px;height:30px;flex:0 0 1px;margin:0 2px;border:0;border-left:1px solid rgba(255,255,255,.18)";
            return;
          }
          group.style.cssText = "display:flex;flex-direction:row;align-items:center;gap:5px;flex:0 0 auto;width:max-content";
          Array.prototype.forEach.call(group.children, function (item) {
            item.style.width = "auto";
            item.style.flex = "0 0 auto";
            var button = item.querySelector("button");
            if (!button) return;
            button.style.width = "42px";
            button.style.height = "42px";
            button.style.minWidth = "42px";
            button.style.minHeight = "42px";
            button.style.flex = "0 0 42px";
          });
        });
        var dockStyle = document.createElement("style");
        dockStyle.textContent = ".hoho-bottom-dock{scrollbar-width:none}.hoho-bottom-dock::-webkit-scrollbar{display:none}.hoho-bottom-dock button{transition:transform 140ms ease,background-color 140ms ease,color 140ms ease}.hoho-bottom-dock button:hover{transform:translateY(-2px);background-color:rgba(255,255,255,.12)}@media(prefers-reduced-motion:reduce){.hoho-bottom-dock button{transition:none}}";
        shadow.appendChild(dockStyle);
      }
      shadow.querySelectorAll("h3").forEach(function (heading) {
        var label = (heading.textContent || "").trim().toLowerCase();
        if (label === "custom theme") {
          heading.parentElement && heading.parentElement.remove();
          return;
        }
        if (label !== "theme") return;
        var section = heading.parentElement;
        if (!section || section.dataset.hohoScale) return;
        var panel = document.createElement("div");
        panel.dataset.hohoScale = "true";
        panel.style.cssText = "display:flex;flex-direction:column;gap:12px;padding:14px;border:1px solid #ffffff24;border-radius:10px;background:#080808;color:#fff";
        var title = document.createElement("h3");
        title.textContent = "Interface scale";
        title.style.cssText = "margin:0;font-size:14px;font-weight:600;color:#fff";
        var row = document.createElement("div");
        row.style.cssText = "display:flex;align-items:center;gap:12px";
        var slider = document.createElement("input");
        slider.type = "range";
        slider.min = "70";
        slider.max = "140";
        slider.step = "5";
        slider.setAttribute("aria-label", "Interface scale");
        slider.style.cssText = "flex:1;min-width:0;min-height:44px;accent-color:#fff";
        var value = document.createElement("output");
        value.style.cssText = "min-width:42px;text-align:right;font-size:13px;color:#ddd";
        var reset = document.createElement("button");
        reset.type = "button";
        reset.textContent = "Reset";
        reset.style.cssText = "min-height:44px;padding:0 14px;border:1px solid #ffffff40;border-radius:7px;background:#111;color:#fff";
        try { slider.value = localStorage.getItem(scaleKey) || "100"; } catch (e) { slider.value = "100"; }
        var update = function () {
          var next = applyScale(slider.value);
          slider.value = String(next);
          value.textContent = next + "%";
        };
        slider.addEventListener("input", update);
        reset.addEventListener("click", function () { slider.value = "100"; update(); });
        row.append(slider, value, reset);
        panel.append(title, row);
        section.replaceWith(panel);
        update();
      });
    };
    var savedScale = 100;
    try { savedScale = Number(localStorage.getItem(scaleKey)) || 100; } catch (e) {}
    applyScale(savedScale);
    clean();
    new MutationObserver(clean).observe(shadow, { childList: true, subtree: true });
  };
  install();
})();
