(function () {
  if (location.pathname !== "/embed") return;
  var mount = document.getElementById("_xi9j4u0");
  var addProxyStyle = function () {
    var shadow = mount && mount.shadowRoot;
    if (!shadow) {
      requestAnimationFrame(addProxyStyle);
      return;
    }
    var style = document.createElement("style");
    style.textContent = "iframe { position: fixed !important; inset: 0 !important; width: 100vw !important; height: 100vh !important; z-index: 2147483647 !important; border: 0 !important; background: #000 !important; }";
    shadow.appendChild(style);
  };
  addProxyStyle();
})();
